"""Canonical GGML IQ2/IQ3 grid data derived from llama.cpp's public reference."""
import base64
import zlib

IQ_GRIDS = {
    'iq2_xxs': ([256,8], ''),
    'iq2_xs': ([512,8], ''),
    'iq2_s': ([1024,8], ''),
    'iq3_xxs': ([256,4], ''),
    'iq3_s': ([512,4], ''),
}


def unpack_grid(name, np):
    shape, encoded = IQ_GRIDS[name]
    return np.frombuffer(zlib.decompress(base64.b64decode(encoded)), dtype=np.uint8).reshape(shape)
